description:
Implement `useDeferredList` — a hook that wraps `useDeferredValue` to provide a deferred version of a list and a staleness flag. Useful for rendering large lists without blocking user interactions.

**Example:**
```tsx
const { deferredItems, isStale } = useDeferredList(expensiveItems);
// isStale is true while React is preparing the deferred render
```

starter_code:
import { useDeferredValue } from 'react';

export function useDeferredList<T>(items: T[]) {
  // your code here
  // return { deferredItems, isStale }
}

test_suite:
test('initially returns items and isStale false', () => {
  const items = [1, 2, 3];
  const { result } = renderHook(() => useDeferredList(items));
  expect(result.current.deferredItems).toEqual([1, 2, 3]);
  expect(result.current.isStale).toBe(false);
});

test('deferredItems eventually matches items', () => {
  const { result, rerender } = renderHook(
    ({ items }) => useDeferredList(items),
    { initialProps: { items: [1, 2, 3] } }
  );
  rerender({ items: [4, 5, 6] });
  expect(result.current.deferredItems).toBeDefined();
});

test('isStale is boolean', () => {
  const { result } = renderHook(() => useDeferredList([1, 2]));
  expect(typeof result.current.isStale).toBe('boolean');
});

test('returns empty array for empty input', () => {
  const { result } = renderHook(() => useDeferredList([]));
  expect(result.current.deferredItems).toEqual([]);
});

// __hidden__
test('deferredItems is the deferred version of items', () => {
  const items = ['a', 'b', 'c'];
  const { result } = renderHook(() => useDeferredList(items));
  expect(Array.isArray(result.current.deferredItems)).toBe(true);
  expect(result.current.deferredItems.length).toBe(3);
});

solution:
import { useDeferredValue } from 'react';

export function useDeferredList<T>(items: T[]) {
  const deferredItems = useDeferredValue(items);
  const isStale = deferredItems !== items;
  return { deferredItems, isStale };
}
